  nombre text, marca text, codigo text, categoria text, colores jsonb, descripcion text,
  divisa_detal numeric, divisa_mayor numeric, bcv_detal numeric, bcv_mayor numeric, precio_antes numeric,
  disponible boolean, encargo boolean, destacado boolean, nuevo boolean, fotos jsonb, colecciones text[],
