where not exists (select 1 from public.productos);

-- Colecciones y reseñas de ejemplo (solo si aún no hay)
update public.config set datos = datos
  || case when coalesce(jsonb_array_length(datos->'colecciones'), 0) = 0 then jsonb_build_object('colecciones', $json$[{"nombre":"Oficina ejecutiva","descripcion":"Presidenciales, escritorios y reunión","imagen":"img/fotos/taburete-velvet-m.webp"},{"nombre":"Hogar","descripcion":"Comedor, barra, espejos y vanity","imagen":"img/fotos/silla-velvet-negra-m.webp"}]$json$::jsonb) else '{}'::jsonb end
  || case when coalesce(jsonb_array_length(datos->'resenas'), 0) = 0 then jsonb_build_object('resenas', $json$[{"nombre":"Grupo Andino C.A.","ciudad":"Valencia","estrellas":5,"texto":"Equipamos toda la gerencia con ARKEO. Calidad impecable y entrega a tiempo."},{"nombre":"Andrea M.","ciudad":"Caracas","estrellas":5,"texto":"El vanity llegó perfecto y muy bien embalado. Excelente atención."},{"nombre":"Despacho Legal R&R","ciudad":"Maracay","estrellas":5,"texto":"Las sillas de visitante y las ejecutivas son muy cómodas. Repetiremos."}]$json$::jsonb) else '{}'::jsonb end
where id = 1;

-- Comprobación: cuántos productos hay ahora
select count(*) as productos_en_la_tienda from public.productos;
